-- Reviewed photo overlay. Publish and verify files before applying.
BEGIN;
SET LOCAL standard_conforming_strings = on;
SELECT pg_advisory_xact_lock(hashtext('mealsolved-recipe-import'));
CREATE TEMP TABLE incoming_photo_updates ON COMMIT DROP AS SELECT value AS item FROM jsonb_array_elements('[{"before":{"id":"41a536a1-ef9f-4744-8d4b-36d2563c462a","title":"Garlic Butter Shrimp Pasta","description":"Spaghetti tossed in a bright garlic butter sauce with lemon juice and tender shrimp — one of the fastest restaurant-quality meals you can make at home. Saving a splash of pasta water before draining is the trick that makes the sauce cling instead of pool at the bottom of the bowl.","meal_time":["dinner"],"prep_time_mins":25,"effort_score":2,"tags":["shrimp","pasta","quick","italian","impressive","seafood"],"image_url":"https://files.manuscdn.com/user_upload_by_module/session_file/310519663417307705/mfrmAYZaAaqNAKqI.jpg","ingredients_list":["12 oz spaghetti","1 lb large frozen shrimp, peeled and deveined","4 tbsp unsalted butter","5 cloves garlic, minced","2 tbsp fresh lemon juice (from 1 lemon)","¼ tsp red pepper flakes","1 tbsp olive oil","3 tbsp fresh parsley, chopped","¼ tsp salt","⅛ tsp black pepper","¼ cup Parmesan cheese, grated (optional)"],"shopping_list":["🥩 Proteins: large frozen shrimp, peeled and deveined","🧀 Dairy: unsalted butter, Parmesan cheese block (optional)","🥬 Produce: garlic, lemon, fresh parsley","🫙 Pantry: spaghetti, olive oil, red pepper flakes, salt, black pepper"],"recipe_steps":["Thaw 1 lb of shrimp in a bowl of cold water for 10 minutes. Drain, pat dry, and season with ¼ tsp salt and ⅛ tsp black pepper. Mince 5 cloves of garlic, squeeze 2 tbsp lemon juice, and chop parsley.","Bring a large pot of salted water to a boil. Cook 12 oz of spaghetti for 9 minutes until al dente. Reserve ¼ cup of pasta water before draining. Drain and set aside.","Heat 1 tbsp olive oil in a large skillet over medium-high heat. Add the shrimp in a single layer and cook for 1–2 minutes until pink on the first side.","Flip each shrimp and cook for 1 more minute until just cooked through. Transfer to a plate.","Reduce heat to medium. Add 4 tbsp butter and the minced garlic to the skillet. Cook for 1 minute, stirring constantly, until golden. Add ¼ tsp red pepper flakes and 2 tbsp lemon juice. Stir and cook 30 seconds.","Add the drained spaghetti and toss until fully coated. Add 2 tbsp reserved pasta water if the pasta looks dry.","Return the shrimp to the skillet, toss everything together, and top with chopped parsley and Parmesan if desired. Serve immediately."],"cuisine":"Italian","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null},"after":{"id":"41a536a1-ef9f-4744-8d4b-36d2563c462a","title":"Garlic Butter Shrimp Pasta","description":"Spaghetti tossed in a bright garlic butter sauce with lemon juice and tender shrimp — one of the fastest restaurant-quality meals you can make at home. Saving a splash of pasta water before draining is the trick that makes the sauce cling instead of pool at the bottom of the bowl.\n\nServing illustration from the existing Mealsolved image library.","meal_time":["dinner"],"prep_time_mins":25,"effort_score":2,"tags":["shrimp","pasta","quick","italian","impressive","seafood"],"image_url":"https://raw.githubusercontent.com/wyattrommel-code/Food-For-you/main/assets/recipe-photos/garlic-butter-shrimp-pasta-2d241cb45138.jpg","ingredients_list":["12 oz spaghetti","1 lb large frozen shrimp, peeled and deveined","4 tbsp unsalted butter","5 cloves garlic, minced","2 tbsp fresh lemon juice (from 1 lemon)","¼ tsp red pepper flakes","1 tbsp olive oil","3 tbsp fresh parsley, chopped","¼ tsp salt","⅛ tsp black pepper","¼ cup Parmesan cheese, grated (optional)"],"shopping_list":["🥩 Proteins: large frozen shrimp, peeled and deveined","🧀 Dairy: unsalted butter, Parmesan cheese block (optional)","🥬 Produce: garlic, lemon, fresh parsley","🫙 Pantry: spaghetti, olive oil, red pepper flakes, salt, black pepper"],"recipe_steps":["Thaw 1 lb of shrimp in a bowl of cold water for 10 minutes. Drain, pat dry, and season with ¼ tsp salt and ⅛ tsp black pepper. Mince 5 cloves of garlic, squeeze 2 tbsp lemon juice, and chop parsley.","Bring a large pot of salted water to a boil. Cook 12 oz of spaghetti for 9 minutes until al dente. Reserve ¼ cup of pasta water before draining. Drain and set aside.","Heat 1 tbsp olive oil in a large skillet over medium-high heat. Add the shrimp in a single layer and cook for 1–2 minutes until pink on the first side.","Flip each shrimp and cook for 1 more minute until just cooked through. Transfer to a plate.","Reduce heat to medium. Add 4 tbsp butter and the minced garlic to the skillet. Cook for 1 minute, stirring constantly, until golden. Add ¼ tsp red pepper flakes and 2 tbsp lemon juice. Stir and cook 30 seconds.","Add the drained spaghetti and toss until fully coated. Add 2 tbsp reserved pasta water if the pasta looks dry.","Return the shrimp to the skillet, toss everything together, and top with chopped parsley and Parmesan if desired. Serve immediately."],"cuisine":"Italian","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null}},{"before":{"id":"9a76d701-d812-433a-bc6e-1d4a9dbab4e5","title":"Chicken and Drop Dumplings","description":"Tender shredded chicken in a thyme-scented broth with pillowy drop dumplings steamed right on top. Pure cold-weather comfort food.","meal_time":["dinner"],"prep_time_mins":55,"effort_score":3,"tags":["chicken","dumplings","soup","comfort-food","southern"],"image_url":"","ingredients_list":["1.5 lbs boneless skinless chicken thighs","3 medium carrots","3 stalks celery","1 small yellow onion","2 garlic cloves","6 cups chicken broth","1 tsp dried thyme","1.5 cups all-purpose flour","2 tsp baking powder","3/4 cup milk","3 tbsp butter","Salt","Black pepper"],"shopping_list":["🥩 Proteins: boneless skinless chicken thighs, chicken broth","🥬 Produce: carrots, celery, yellow onion, garlic cloves","🧀 Dairy: milk, butter","🫙 Pantry: dried thyme, all-purpose flour, baking powder, salt, black pepper"],"recipe_steps":["Broth base: Peel and slice the carrots into 1/4-inch rounds. Wash and slice the celery. Peel and dice the onion. Peel and mince 2 garlic cloves.","Melt 1 tbsp butter in a large pot over medium heat. Add the onion and cook 3 minutes, then add carrots and celery and cook 3 minutes, then the garlic for 1 minute.","Add 1.5 lbs chicken thighs and pour in 6 cups chicken broth. Add 1 tsp dried thyme and season with 1/2 tsp salt and 1/4 tsp pepper.","Bring to a boil, reduce to medium-low, and cook 20 minutes until the chicken is cooked through.","Remove the chicken, shred with two forks, and return it to the pot.","Dumplings: In a bowl, whisk 1.5 cups flour, 2 tsp baking powder, and 1/2 tsp salt. Microwave 2 tbsp butter 20 seconds until melted.","Pour the melted butter and 3/4 cup milk into the flour and stir until a soft, shaggy dough just comes together — do not overmix.","Bring the soup to a gentle simmer. Drop tablespoon-sized portions of dough into the soup.","Cover and cook 12 to 15 minutes without lifting the lid, until the dumplings are puffed and cooked through. Ladle into bowls and serve immediately."],"cuisine":"American","created_at":"2026-06-08 12:00:00+00","servings":6,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null},"after":{"id":"9a76d701-d812-433a-bc6e-1d4a9dbab4e5","title":"Chicken and Drop Dumplings","description":"Tender shredded chicken in a thyme-scented broth with pillowy drop dumplings steamed right on top. Pure cold-weather comfort food.\n\nServing illustration from the existing Mealsolved image library.","meal_time":["dinner"],"prep_time_mins":55,"effort_score":3,"tags":["chicken","dumplings","soup","comfort-food","southern"],"image_url":"https://raw.githubusercontent.com/wyattrommel-code/Food-For-you/main/assets/recipe-photos/chicken-and-drop-dumplings-394aa0b705d2.jpg","ingredients_list":["1.5 lbs boneless skinless chicken thighs","3 medium carrots","3 stalks celery","1 small yellow onion","2 garlic cloves","6 cups chicken broth","1 tsp dried thyme","1.5 cups all-purpose flour","2 tsp baking powder","3/4 cup milk","3 tbsp butter","Salt","Black pepper"],"shopping_list":["🥩 Proteins: boneless skinless chicken thighs, chicken broth","🥬 Produce: carrots, celery, yellow onion, garlic cloves","🧀 Dairy: milk, butter","🫙 Pantry: dried thyme, all-purpose flour, baking powder, salt, black pepper"],"recipe_steps":["Broth base: Peel and slice the carrots into 1/4-inch rounds. Wash and slice the celery. Peel and dice the onion. Peel and mince 2 garlic cloves.","Melt 1 tbsp butter in a large pot over medium heat. Add the onion and cook 3 minutes, then add carrots and celery and cook 3 minutes, then the garlic for 1 minute.","Add 1.5 lbs chicken thighs and pour in 6 cups chicken broth. Add 1 tsp dried thyme and season with 1/2 tsp salt and 1/4 tsp pepper.","Bring to a boil, reduce to medium-low, and cook 20 minutes until the chicken is cooked through.","Remove the chicken, shred with two forks, and return it to the pot.","Dumplings: In a bowl, whisk 1.5 cups flour, 2 tsp baking powder, and 1/2 tsp salt. Microwave 2 tbsp butter 20 seconds until melted.","Pour the melted butter and 3/4 cup milk into the flour and stir until a soft, shaggy dough just comes together — do not overmix.","Bring the soup to a gentle simmer. Drop tablespoon-sized portions of dough into the soup.","Cover and cook 12 to 15 minutes without lifting the lid, until the dumplings are puffed and cooked through. Ladle into bowls and serve immediately."],"cuisine":"American","created_at":"2026-06-08 12:00:00+00","servings":6,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null}},{"before":{"id":"48248a2f-6951-41e3-9894-edc319bb3cb3","title":"Shortcut Rotisserie Chicken Noodle Soup","description":"A fast homemade chicken noodle soup that uses store-bought rotisserie chicken to skip the long simmer. Loaded with carrots, celery, and egg noodles.","meal_time":["dinner","lunch"],"prep_time_mins":35,"effort_score":2,"tags":["soup","chicken","comfort-food","quick","family"],"image_url":"","ingredients_list":["1 store-bought rotisserie chicken","3 medium carrots","3 stalks celery","1 small yellow onion","3 garlic cloves","8 cups chicken broth","2 cups egg noodles (uncooked)","1 tsp dried thyme","1 tbsp butter","Salt","Black pepper"],"shopping_list":["🥩 Proteins: rotisserie chicken, chicken broth","🥬 Produce: carrots, celery, yellow onion, garlic cloves","🍞 Pantry: egg noodles, dried thyme, salt, black pepper","🧀 Dairy: butter"],"recipe_steps":["Pull the meat off the rotisserie chicken and shred into bite-sized pieces with two forks. Discard the carcass and skin.","Peel and slice the carrots into 1/4-inch rounds. Wash and slice the celery. Peel and dice the onion. Peel and mince 3 garlic cloves.","Melt 1 tbsp butter in a large pot over medium heat. Add the onion and cook 3 minutes until softened.","Add the carrots and celery and cook 3 minutes, then add the garlic and cook 1 minute.","Pour in 8 cups chicken broth, add 1 tsp dried thyme, and season with 1/2 tsp salt and 1/4 tsp pepper. Bring to a boil.","Add 2 cups egg noodles and cook 8 minutes until tender.","Add the shredded chicken, stir, and cook 2 minutes to heat through. Taste, adjust seasoning, and serve."],"cuisine":"American","created_at":"2026-06-08 12:00:00+00","servings":6,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null},"after":{"id":"48248a2f-6951-41e3-9894-edc319bb3cb3","title":"Shortcut Rotisserie Chicken Noodle Soup","description":"A fast homemade chicken noodle soup that uses store-bought rotisserie chicken to skip the long simmer. Loaded with carrots, celery, and egg noodles.\n\nServing illustration from the existing Mealsolved image library.","meal_time":["dinner","lunch"],"prep_time_mins":35,"effort_score":2,"tags":["soup","chicken","comfort-food","quick","family"],"image_url":"https://raw.githubusercontent.com/wyattrommel-code/Food-For-you/main/assets/recipe-photos/shortcut-rotisserie-chicken-noodle-soup-1b42ed469721.jpg","ingredients_list":["1 store-bought rotisserie chicken","3 medium carrots","3 stalks celery","1 small yellow onion","3 garlic cloves","8 cups chicken broth","2 cups egg noodles (uncooked)","1 tsp dried thyme","1 tbsp butter","Salt","Black pepper"],"shopping_list":["🥩 Proteins: rotisserie chicken, chicken broth","🥬 Produce: carrots, celery, yellow onion, garlic cloves","🍞 Pantry: egg noodles, dried thyme, salt, black pepper","🧀 Dairy: butter"],"recipe_steps":["Pull the meat off the rotisserie chicken and shred into bite-sized pieces with two forks. Discard the carcass and skin.","Peel and slice the carrots into 1/4-inch rounds. Wash and slice the celery. Peel and dice the onion. Peel and mince 3 garlic cloves.","Melt 1 tbsp butter in a large pot over medium heat. Add the onion and cook 3 minutes until softened.","Add the carrots and celery and cook 3 minutes, then add the garlic and cook 1 minute.","Pour in 8 cups chicken broth, add 1 tsp dried thyme, and season with 1/2 tsp salt and 1/4 tsp pepper. Bring to a boil.","Add 2 cups egg noodles and cook 8 minutes until tender.","Add the shredded chicken, stir, and cook 2 minutes to heat through. Taste, adjust seasoning, and serve."],"cuisine":"American","created_at":"2026-06-08 12:00:00+00","servings":6,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null}},{"before":{"id":"ee43ef89-dbab-49ab-9e34-a1f2e1ccae62","title":"Skillet Chicken Fajitas","description":"Thin-sliced chicken breast and charred peppers and onions cooked in a screaming-hot skillet, finished with fresh lime juice. Cooking the chicken first and resting it while the vegetables go means nothing gets overcooked.","meal_time":["dinner","lunch"],"prep_time_mins":25,"effort_score":2,"tags":["chicken","mexican","quick","spicy","one-pan","kid-friendly"],"image_url":"https://files.manuscdn.com/user_upload_by_module/session_file/310519663417307705/JuuRyjPaAHBRBFiU.jpg","ingredients_list":["1½ lbs boneless skinless chicken breast, sliced into ¼-inch strips","1 green bell pepper, sliced into thin strips","1 red bell pepper, sliced into thin strips","1 large yellow onion, sliced into thin strips","2 tbsp lime juice (from 1 lime)","3 tbsp olive oil, divided","1 tsp chili powder","1 tsp cumin","½ tsp smoked paprika","½ tsp garlic powder","½ tsp onion powder","½ tsp salt","¼ tsp black pepper","8-inch flour tortillas, for serving","½ cup cheddar cheese, grated","Sour cream, for serving","Salsa, for serving"],"shopping_list":["🥩 Proteins: boneless skinless chicken breast","🧀 Dairy: cheddar cheese block, sour cream","🥬 Produce: green bell pepper, red bell pepper, yellow onion, lime","🍞 Bread: flour tortillas","🛒 Other: salsa","🫙 Pantry: olive oil, chili powder, cumin, smoked paprika, garlic powder, onion powder, salt, black pepper"],"recipe_steps":["Slice 1½ lbs of chicken breast into thin ¼-inch strips. Slice peppers and onion into strips. Squeeze 2 tbsp lime juice. Grate ½ cup cheddar.","Toss the chicken strips with 1 tsp chili powder, 1 tsp cumin, ½ tsp smoked paprika, ½ tsp garlic powder, ½ tsp onion powder, ½ tsp salt, and ¼ tsp black pepper until evenly coated.","Heat 2 tbsp olive oil in a large skillet over high heat. Add the seasoned chicken in a single layer and cook for 3 minutes without stirring until browned on the bottom.","Flip the chicken and cook for 2 more minutes until cooked through. Transfer to a plate.","Add 1 tbsp olive oil to the same skillet. Add the sliced peppers and onion and cook for 5–6 minutes, stirring occasionally, until softened and lightly charred.","Return the chicken to the skillet, pour the lime juice over everything, toss together, and cook for 1 more minute.","Warm flour tortillas in a dry skillet for 20 seconds per side. Serve the chicken and vegetables directly from the skillet with warm tortillas, grated cheddar, sour cream, and salsa on the side."],"cuisine":"Mexican","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null},"after":{"id":"ee43ef89-dbab-49ab-9e34-a1f2e1ccae62","title":"Skillet Chicken Fajitas","description":"Thin-sliced chicken breast and charred peppers and onions cooked in a screaming-hot skillet, finished with fresh lime juice. Cooking the chicken first and resting it while the vegetables go means nothing gets overcooked.\n\nServing illustration from the existing Mealsolved image library.","meal_time":["dinner","lunch"],"prep_time_mins":25,"effort_score":2,"tags":["chicken","mexican","quick","spicy","one-pan","kid-friendly"],"image_url":"https://raw.githubusercontent.com/wyattrommel-code/Food-For-you/main/assets/recipe-photos/skillet-chicken-fajitas-ce18ddab9779.jpg","ingredients_list":["1½ lbs boneless skinless chicken breast, sliced into ¼-inch strips","1 green bell pepper, sliced into thin strips","1 red bell pepper, sliced into thin strips","1 large yellow onion, sliced into thin strips","2 tbsp lime juice (from 1 lime)","3 tbsp olive oil, divided","1 tsp chili powder","1 tsp cumin","½ tsp smoked paprika","½ tsp garlic powder","½ tsp onion powder","½ tsp salt","¼ tsp black pepper","8-inch flour tortillas, for serving","½ cup cheddar cheese, grated","Sour cream, for serving","Salsa, for serving"],"shopping_list":["🥩 Proteins: boneless skinless chicken breast","🧀 Dairy: cheddar cheese block, sour cream","🥬 Produce: green bell pepper, red bell pepper, yellow onion, lime","🍞 Bread: flour tortillas","🛒 Other: salsa","🫙 Pantry: olive oil, chili powder, cumin, smoked paprika, garlic powder, onion powder, salt, black pepper"],"recipe_steps":["Slice 1½ lbs of chicken breast into thin ¼-inch strips. Slice peppers and onion into strips. Squeeze 2 tbsp lime juice. Grate ½ cup cheddar.","Toss the chicken strips with 1 tsp chili powder, 1 tsp cumin, ½ tsp smoked paprika, ½ tsp garlic powder, ½ tsp onion powder, ½ tsp salt, and ¼ tsp black pepper until evenly coated.","Heat 2 tbsp olive oil in a large skillet over high heat. Add the seasoned chicken in a single layer and cook for 3 minutes without stirring until browned on the bottom.","Flip the chicken and cook for 2 more minutes until cooked through. Transfer to a plate.","Add 1 tbsp olive oil to the same skillet. Add the sliced peppers and onion and cook for 5–6 minutes, stirring occasionally, until softened and lightly charred.","Return the chicken to the skillet, pour the lime juice over everything, toss together, and cook for 1 more minute.","Warm flour tortillas in a dry skillet for 20 seconds per side. Serve the chicken and vegetables directly from the skillet with warm tortillas, grated cheddar, sour cream, and salsa on the side."],"cuisine":"Mexican","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null}},{"before":{"id":"fbe9af8e-e8dc-4b23-b1a8-717c2f9988f7","title":"Fried Egg Sandwich","description":"A diner-style fried egg sandwich with melted American cheese on toast. Eggs are cooked over-medium so the yolk stays just soft, then layered with cheese and pressed between toasted bread.","meal_time":["breakfast","lunch"],"prep_time_mins":10,"effort_score":1,"tags":["eggs","sandwich","quick","breakfast"],"image_url":"","ingredients_list":["2 large eggs","2 slices white sandwich bread","2 slices American cheese","1 tbsp butter","Salt","Black pepper"],"shopping_list":["🥩 Proteins: large eggs","🧀 Dairy: American cheese, butter","🍞 Bread: white sandwich bread","🫙 Pantry: salt, black pepper"],"recipe_steps":["Set a skillet over medium heat and add 1 tbsp butter. Let it melt completely, about 1 minute.","Crack 2 eggs into the skillet and season each with a pinch of salt and black pepper.","Cook for 2 minutes until the whites are fully set but the yolks are still soft.","Flip each egg with a spatula and cook for 30 seconds more.","Remove the skillet from heat. Place 1 slice of American cheese on each egg and let melt for 30 seconds from residual heat.","Toast 2 slices of bread in a toaster.","Place both eggs on one slice of toast, top with the second slice, slice in half, and serve immediately."],"cuisine":"American","created_at":"2026-06-08 12:00:00+00","servings":1,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null},"after":{"id":"fbe9af8e-e8dc-4b23-b1a8-717c2f9988f7","title":"Fried Egg Sandwich","description":"A diner-style fried egg sandwich with melted American cheese on toast. Eggs are cooked over-medium so the yolk stays just soft, then layered with cheese and pressed between toasted bread.\n\nRepresentative photo: \"Egg and Cheese breakfast sandwich on rye bread.jpg\" by Robert Loescher, CC BY-SA 4.0. Resized and converted to JPEG. This image adaptation remains licensed under CC BY-SA 4.0. Shown on rye bread; this recipe uses white bread. Source: https://commons.wikimedia.org/wiki/File:Egg_and_Cheese_breakfast_sandwich_on_rye_bread.jpg License: https://creativecommons.org/licenses/by-sa/4.0","meal_time":["breakfast","lunch"],"prep_time_mins":10,"effort_score":1,"tags":["eggs","sandwich","quick","breakfast"],"image_url":"https://raw.githubusercontent.com/wyattrommel-code/Food-For-you/main/assets/recipe-photos/fried-egg-sandwich-928d1424a6e6.jpg","ingredients_list":["2 large eggs","2 slices white sandwich bread","2 slices American cheese","1 tbsp butter","Salt","Black pepper"],"shopping_list":["🥩 Proteins: large eggs","🧀 Dairy: American cheese, butter","🍞 Bread: white sandwich bread","🫙 Pantry: salt, black pepper"],"recipe_steps":["Set a skillet over medium heat and add 1 tbsp butter. Let it melt completely, about 1 minute.","Crack 2 eggs into the skillet and season each with a pinch of salt and black pepper.","Cook for 2 minutes until the whites are fully set but the yolks are still soft.","Flip each egg with a spatula and cook for 30 seconds more.","Remove the skillet from heat. Place 1 slice of American cheese on each egg and let melt for 30 seconds from residual heat.","Toast 2 slices of bread in a toaster.","Place both eggs on one slice of toast, top with the second slice, slice in half, and serve immediately."],"cuisine":"American","created_at":"2026-06-08 12:00:00+00","servings":1,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null}},{"before":{"id":"c653bb10-2153-4261-82e6-79cb2c31a894","title":"Simple Potato Soup","description":"A creamy, partially-mashed potato soup finished with milk, sour cream, and cheddar. Cozy and thick without needing any cream.","meal_time":["dinner","lunch"],"prep_time_mins":40,"effort_score":2,"tags":["soup","potatoes","comfort-food","vegetarian-option"],"image_url":"","ingredients_list":["5 medium russet potatoes","1 small yellow onion","3 garlic cloves","3 cups chicken broth","1 cup milk","1/2 cup sour cream","1/2 cup shredded cheddar cheese","3 tbsp butter","Salt","Black pepper"],"shopping_list":["🥬 Produce: russet potatoes, yellow onion, garlic cloves","🥩 Proteins: chicken broth","🧀 Dairy: milk, sour cream, shredded cheddar cheese, butter","🫙 Pantry: salt, black pepper"],"recipe_steps":["Peel the potatoes and cut into 1-inch cubes. Peel and dice the onion. Peel and mince 3 garlic cloves.","Melt 3 tbsp butter in a large pot over medium heat. Add the onion and cook 4 minutes until softened.","Add the garlic and cook 1 minute, stirring constantly.","Add the potato cubes and 3 cups chicken broth. Season with 1/2 tsp salt and 1/4 tsp pepper.","Bring to a boil, then reduce to medium-low and cook 15 minutes until the potatoes are fork-tender.","Mash about half the potatoes directly in the pot with a potato masher, then stir to combine.","Pour in 1 cup milk, stir, and cook over medium heat 5 minutes until heated through.","Remove from heat and stir in 1/2 cup sour cream. Taste and adjust seasoning.","Ladle into bowls and top each with 2 tbsp shredded cheddar. Serve immediately."],"cuisine":"American","created_at":"2026-06-08 12:00:00+00","servings":6,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null},"after":{"id":"c653bb10-2153-4261-82e6-79cb2c31a894","title":"Simple Potato Soup","description":"A creamy, partially-mashed potato soup finished with milk, sour cream, and cheddar. Cozy and thick without needing any cream.\n\nRepresentative photo: \"Cheddar potato soup.jpg\" by Jessica Diamond, CC BY-SA 2.0. Resized and converted to JPEG. This image adaptation remains licensed under CC BY-SA 2.0. Shown with a smooth texture; mash the potatoes to your preference. Source: https://commons.wikimedia.org/wiki/File:Cheddar_potato_soup.jpg License: https://creativecommons.org/licenses/by-sa/2.0","meal_time":["dinner","lunch"],"prep_time_mins":40,"effort_score":2,"tags":["soup","potatoes","comfort-food","vegetarian-option"],"image_url":"https://raw.githubusercontent.com/wyattrommel-code/Food-For-you/main/assets/recipe-photos/simple-potato-soup-0319c771b53e.jpg","ingredients_list":["5 medium russet potatoes","1 small yellow onion","3 garlic cloves","3 cups chicken broth","1 cup milk","1/2 cup sour cream","1/2 cup shredded cheddar cheese","3 tbsp butter","Salt","Black pepper"],"shopping_list":["🥬 Produce: russet potatoes, yellow onion, garlic cloves","🥩 Proteins: chicken broth","🧀 Dairy: milk, sour cream, shredded cheddar cheese, butter","🫙 Pantry: salt, black pepper"],"recipe_steps":["Peel the potatoes and cut into 1-inch cubes. Peel and dice the onion. Peel and mince 3 garlic cloves.","Melt 3 tbsp butter in a large pot over medium heat. Add the onion and cook 4 minutes until softened.","Add the garlic and cook 1 minute, stirring constantly.","Add the potato cubes and 3 cups chicken broth. Season with 1/2 tsp salt and 1/4 tsp pepper.","Bring to a boil, then reduce to medium-low and cook 15 minutes until the potatoes are fork-tender.","Mash about half the potatoes directly in the pot with a potato masher, then stir to combine.","Pour in 1 cup milk, stir, and cook over medium heat 5 minutes until heated through.","Remove from heat and stir in 1/2 cup sour cream. Taste and adjust seasoning.","Ladle into bowls and top each with 2 tbsp shredded cheddar. Serve immediately."],"cuisine":"American","created_at":"2026-06-08 12:00:00+00","servings":6,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null}},{"before":{"id":"f0ab42dc-093e-485c-a9ef-30170feaf6a6","title":"Southern Fried Potatoes and Onions","description":"Crispy skillet potatoes fried with sweet onions, garlic powder, and paprika. A Southern classic that crisps on the outside while staying fork-tender inside.","meal_time":["sides"],"prep_time_mins":30,"effort_score":1,"tags":["potatoes","sides","vegetarian","comfort-food"],"image_url":"","ingredients_list":["4 medium russet potatoes","1 large yellow onion","3 tbsp vegetable oil","1/2 tsp garlic powder","1/2 tsp paprika","Salt","Black pepper"],"shopping_list":["🥬 Produce: russet potatoes, yellow onion","🫙 Pantry: vegetable oil, garlic powder, paprika, salt, black pepper"],"recipe_steps":["Wash and peel the potatoes, then slice into 1/4-inch rounds. Peel and slice the onion into 1/4-inch rings.","Heat 3 tbsp vegetable oil in a large cast iron skillet over medium-high heat.","Add the potato slices in a single layer and season with 1/4 tsp salt and 1/4 tsp pepper. Cook 5 minutes without stirring until the bottom is golden.","Flip the potatoes, scatter the onion rings over top, and sprinkle with 1/4 tsp garlic powder and 1/4 tsp paprika. Cook 5 minutes, stirring occasionally.","Reduce heat to medium-low, cover, and cook 10 minutes, stirring every few minutes, until fork-tender.","Remove the lid, increase heat to medium-high, and cook 3 more minutes until crispy. Taste, adjust seasoning, and serve hot."],"cuisine":"American","created_at":"2026-06-08 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null},"after":{"id":"f0ab42dc-093e-485c-a9ef-30170feaf6a6","title":"Southern Fried Potatoes and Onions","description":"Crispy skillet potatoes fried with sweet onions, garlic powder, and paprika. A Southern classic that crisps on the outside while staying fork-tender inside.\n\nRepresentative photo: \"Potatoes, fried with salt and pepper - Arlington, MA.jpg\" by Daderot, CC0. Resized and converted to JPEG. Photo shows the fried potatoes; this recipe also includes onions. Source: https://commons.wikimedia.org/wiki/File:Potatoes,_fried_with_salt_and_pepper_-_Arlington,_MA.jpg License: https://creativecommons.org/publicdomain/zero/1.0/deed.en","meal_time":["sides"],"prep_time_mins":30,"effort_score":1,"tags":["potatoes","sides","vegetarian","comfort-food"],"image_url":"https://raw.githubusercontent.com/wyattrommel-code/Food-For-you/main/assets/recipe-photos/southern-fried-potatoes-and-onions-f2444f6996c1.jpg","ingredients_list":["4 medium russet potatoes","1 large yellow onion","3 tbsp vegetable oil","1/2 tsp garlic powder","1/2 tsp paprika","Salt","Black pepper"],"shopping_list":["🥬 Produce: russet potatoes, yellow onion","🫙 Pantry: vegetable oil, garlic powder, paprika, salt, black pepper"],"recipe_steps":["Wash and peel the potatoes, then slice into 1/4-inch rounds. Peel and slice the onion into 1/4-inch rings.","Heat 3 tbsp vegetable oil in a large cast iron skillet over medium-high heat.","Add the potato slices in a single layer and season with 1/4 tsp salt and 1/4 tsp pepper. Cook 5 minutes without stirring until the bottom is golden.","Flip the potatoes, scatter the onion rings over top, and sprinkle with 1/4 tsp garlic powder and 1/4 tsp paprika. Cook 5 minutes, stirring occasionally.","Reduce heat to medium-low, cover, and cook 10 minutes, stirring every few minutes, until fork-tender.","Remove the lid, increase heat to medium-high, and cook 3 more minutes until crispy. Taste, adjust seasoning, and serve hot."],"cuisine":"American","created_at":"2026-06-08 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null}},{"before":{"id":"640b90af-82ec-41fa-a292-0b614f6529ca","title":"20-Minute Honey Garlic Chicken","description":"Boneless chicken thighs seared until deeply golden, then glazed in a sweet and savory honey garlic sauce that clings to every bite. Letting the thighs cook undisturbed for 5 minutes on the first side is what builds the crust the sauce sticks to.","meal_time":["dinner"],"prep_time_mins":20,"effort_score":2,"tags":["chicken","quick","one-pan","asian","kid-friendly","comfort-food"],"image_url":"https://files.manuscdn.com/user_upload_by_module/session_file/310519663417307705/uBqtvXRjmmMrKlrt.jpg","ingredients_list":["1½ lbs boneless skinless chicken thighs","5 cloves garlic, minced","1 tbsp unsalted butter","¼ cup honey","3 tbsp soy sauce","1 tbsp apple cider vinegar","1 tsp cornstarch","2 tbsp olive oil","½ tsp salt","¼ tsp black pepper","2 tbsp fresh parsley, chopped","2 cups white rice, for serving"],"shopping_list":["🥩 Proteins: boneless skinless chicken thighs","🧀 Dairy: unsalted butter","🥬 Produce: garlic, fresh parsley","🫙 Pantry: honey, soy sauce, apple cider vinegar, cornstarch, olive oil, salt, black pepper, white rice"],"recipe_steps":["Start 2 cups of white rice cooking. Pat 1½ lbs of chicken thighs dry and season both sides with ½ tsp salt and ¼ tsp black pepper. Mince 5 cloves of garlic.","Whisk together ¼ cup honey, 3 tbsp soy sauce, 1 tbsp apple cider vinegar, and 1 tsp cornstarch until the cornstarch fully dissolves. Set aside.","Heat 2 tbsp olive oil in a large skillet over medium-high heat. Add the chicken thighs and cook for 5 minutes without moving until deeply golden brown on the bottom.","Flip each thigh and cook for 4 more minutes until the second side is golden and cooked through. Transfer to a plate.","Reduce heat to medium. Add 1 tbsp butter and the minced garlic to the skillet. Cook for 1 minute, stirring constantly, until golden.","Pour the honey soy sauce into the skillet. Stir and cook for 1–2 minutes until the sauce bubbles and thickens.","Return the chicken to the skillet, spoon sauce over each piece, and cook 1 more minute. Serve over rice and sprinkle with 2 tbsp chopped parsley."],"cuisine":"Asian","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null},"after":{"id":"640b90af-82ec-41fa-a292-0b614f6529ca","title":"20-Minute Honey Garlic Chicken","description":"Boneless chicken thighs seared until deeply golden, then glazed in a sweet and savory honey garlic sauce that clings to every bite. Letting the thighs cook undisturbed for 5 minutes on the first side is what builds the crust the sauce sticks to.","meal_time":["dinner"],"prep_time_mins":20,"effort_score":2,"tags":["chicken","quick","one-pan","asian","kid-friendly","comfort-food"],"image_url":"","ingredients_list":["1½ lbs boneless skinless chicken thighs","5 cloves garlic, minced","1 tbsp unsalted butter","¼ cup honey","3 tbsp soy sauce","1 tbsp apple cider vinegar","1 tsp cornstarch","2 tbsp olive oil","½ tsp salt","¼ tsp black pepper","2 tbsp fresh parsley, chopped","2 cups white rice, for serving"],"shopping_list":["🥩 Proteins: boneless skinless chicken thighs","🧀 Dairy: unsalted butter","🥬 Produce: garlic, fresh parsley","🫙 Pantry: honey, soy sauce, apple cider vinegar, cornstarch, olive oil, salt, black pepper, white rice"],"recipe_steps":["Start 2 cups of white rice cooking. Pat 1½ lbs of chicken thighs dry and season both sides with ½ tsp salt and ¼ tsp black pepper. Mince 5 cloves of garlic.","Whisk together ¼ cup honey, 3 tbsp soy sauce, 1 tbsp apple cider vinegar, and 1 tsp cornstarch until the cornstarch fully dissolves. Set aside.","Heat 2 tbsp olive oil in a large skillet over medium-high heat. Add the chicken thighs and cook for 5 minutes without moving until deeply golden brown on the bottom.","Flip each thigh and cook for 4 more minutes until the second side is golden and cooked through. Transfer to a plate.","Reduce heat to medium. Add 1 tbsp butter and the minced garlic to the skillet. Cook for 1 minute, stirring constantly, until golden.","Pour the honey soy sauce into the skillet. Stir and cook for 1–2 minutes until the sauce bubbles and thickens.","Return the chicken to the skillet, spoon sauce over each piece, and cook 1 more minute. Serve over rice and sprinkle with 2 tbsp chopped parsley."],"cuisine":"Asian","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null}},{"before":{"id":"eace11b6-3fe4-4d13-ae37-eaaafe7d7ef1","title":"One-Pan Creamy Chicken and Rice","description":"Bite-sized chicken thighs and long-grain rice cooked together in a creamy, herb-seasoned broth until everything is tender and the sauce is absorbed. A tight-fitting lid during the final 18-minute simmer is non-negotiable — lifting it lets the steam escape and the rice won''t cook through.","meal_time":["dinner"],"prep_time_mins":30,"effort_score":2,"tags":["chicken","one-pan","comfort-food","rice","kid-friendly","make-ahead"],"image_url":"https://files.manuscdn.com/user_upload_by_module/session_file/310519663417307705/qSDVoGmauzWSWIIK.jpg","ingredients_list":["1½ lbs boneless skinless chicken thighs, cut into 1-inch pieces","1½ cups white long-grain rice","2½ cups chicken broth","½ cup heavy cream","½ yellow onion, finely diced","4 cloves garlic, minced","3 tbsp unsalted butter, divided","½ tsp garlic powder","½ tsp onion powder","½ tsp dried thyme","½ tsp dried parsley","½ tsp salt","¼ tsp black pepper","¼ cup Parmesan cheese, grated (optional)"],"shopping_list":["🥩 Proteins: boneless skinless chicken thighs","🧀 Dairy: heavy cream, unsalted butter, Parmesan cheese block (optional)","🥬 Produce: yellow onion, garlic","🥫 Canned: chicken broth","🫙 Pantry: white long-grain rice, garlic powder, onion powder, dried thyme, dried parsley, salt, black pepper"],"recipe_steps":["Cut 1½ lbs chicken thighs into 1-inch pieces and pat dry. Season with ½ tsp salt, ¼ tsp black pepper, and ½ tsp garlic powder. Dice onion, mince garlic, and grate Parmesan if using.","Melt 2 tbsp butter in a large deep skillet over medium-high heat. Add the chicken and cook for 4 minutes until golden on the outside. Transfer to a plate — it will finish cooking with the rice.","Add 1 tbsp butter to the skillet. Add the diced onion and cook for 3 minutes until softened. Add the minced garlic and cook 1 minute, stirring constantly.","Add 1½ cups of white rice and stir into the vegetables. Cook for 1 minute to toast lightly.","Pour in 2½ cups of chicken broth and ½ cup of heavy cream. Add ½ tsp dried thyme, ½ tsp dried parsley, ½ tsp onion powder, and ½ tsp salt. Stir everything together.","Return the chicken to the skillet. Bring to a boil over high heat, then reduce to low and cover with a tight-fitting lid. Cook for 18 minutes until all liquid is absorbed and the rice is tender — do not lift the lid.","Remove from heat, sprinkle with Parmesan if using, fluff with a fork, and serve directly from the skillet."],"cuisine":"American","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null},"after":{"id":"eace11b6-3fe4-4d13-ae37-eaaafe7d7ef1","title":"One-Pan Creamy Chicken and Rice","description":"Bite-sized chicken thighs and long-grain rice cooked together in a creamy, herb-seasoned broth until everything is tender and the sauce is absorbed. A tight-fitting lid during the final 18-minute simmer is non-negotiable — lifting it lets the steam escape and the rice won''t cook through.","meal_time":["dinner"],"prep_time_mins":30,"effort_score":2,"tags":["chicken","one-pan","comfort-food","rice","kid-friendly","make-ahead"],"image_url":"","ingredients_list":["1½ lbs boneless skinless chicken thighs, cut into 1-inch pieces","1½ cups white long-grain rice","2½ cups chicken broth","½ cup heavy cream","½ yellow onion, finely diced","4 cloves garlic, minced","3 tbsp unsalted butter, divided","½ tsp garlic powder","½ tsp onion powder","½ tsp dried thyme","½ tsp dried parsley","½ tsp salt","¼ tsp black pepper","¼ cup Parmesan cheese, grated (optional)"],"shopping_list":["🥩 Proteins: boneless skinless chicken thighs","🧀 Dairy: heavy cream, unsalted butter, Parmesan cheese block (optional)","🥬 Produce: yellow onion, garlic","🥫 Canned: chicken broth","🫙 Pantry: white long-grain rice, garlic powder, onion powder, dried thyme, dried parsley, salt, black pepper"],"recipe_steps":["Cut 1½ lbs chicken thighs into 1-inch pieces and pat dry. Season with ½ tsp salt, ¼ tsp black pepper, and ½ tsp garlic powder. Dice onion, mince garlic, and grate Parmesan if using.","Melt 2 tbsp butter in a large deep skillet over medium-high heat. Add the chicken and cook for 4 minutes until golden on the outside. Transfer to a plate — it will finish cooking with the rice.","Add 1 tbsp butter to the skillet. Add the diced onion and cook for 3 minutes until softened. Add the minced garlic and cook 1 minute, stirring constantly.","Add 1½ cups of white rice and stir into the vegetables. Cook for 1 minute to toast lightly.","Pour in 2½ cups of chicken broth and ½ cup of heavy cream. Add ½ tsp dried thyme, ½ tsp dried parsley, ½ tsp onion powder, and ½ tsp salt. Stir everything together.","Return the chicken to the skillet. Bring to a boil over high heat, then reduce to low and cover with a tight-fitting lid. Cook for 18 minutes until all liquid is absorbed and the rice is tender — do not lift the lid.","Remove from heat, sprinkle with Parmesan if using, fluff with a fork, and serve directly from the skillet."],"cuisine":"American","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null}},{"before":{"id":"7536d75f-5abd-404a-9755-c8f28a828992","title":"One-Pot Creamy Sausage Pasta","description":"Smoked sausage, rotini pasta, and diced tomatoes simmered together in a creamy, spiced sauce — everything cooks in one pot and the pasta soaks up the flavor as it goes. Stirring every few minutes during the uncovered simmer prevents sticking and helps the sauce thicken evenly.","meal_time":["dinner"],"prep_time_mins":25,"effort_score":2,"tags":["sausage","pasta","one-pot","comfort-food","quick","kid-friendly"],"image_url":"https://files.manuscdn.com/user_upload_by_module/session_file/310519663417307705/NZwKyHhmXuvRfyze.jpg","ingredients_list":["14 oz smoked sausage (kielbasa), sliced into ½-inch rounds","2 cups dry rotini or penne pasta","2 cups chicken broth","1 cup heavy cream","14 oz diced tomatoes (1 can), with liquid","½ yellow onion, finely diced","4 cloves garlic, minced","1 tbsp olive oil","1 tsp Italian seasoning","½ tsp smoked paprika","½ tsp salt","¼ tsp black pepper","½ cup Parmesan cheese, grated","2 tbsp fresh parsley, chopped"],"shopping_list":["🥩 Proteins: smoked sausage (kielbasa)","🧀 Dairy: heavy cream, Parmesan cheese block","🥬 Produce: yellow onion, garlic, fresh parsley","🥫 Canned: chicken broth, diced tomatoes","🫙 Pantry: rotini or penne pasta, olive oil, Italian seasoning, smoked paprika, salt, black pepper"],"recipe_steps":["Slice sausage into ½-inch rounds. Dice onion, mince garlic, grate Parmesan, and chop parsley.","Heat 1 tbsp olive oil in a large pot over medium-high heat. Add sausage rounds and cook for 3 minutes until browned on one side, then flip and cook 2 more minutes. Transfer to a plate.","Add the diced onion to the pot and cook for 3 minutes, stirring occasionally. Add the minced garlic and cook 1 minute, stirring constantly.","Add 1 tsp Italian seasoning, ½ tsp smoked paprika, ½ tsp salt, and ¼ tsp black pepper. Stir for 30 seconds.","Pour in 2 cups chicken broth, 1 cup heavy cream, and one 14-oz can of diced tomatoes with all its liquid. Add 2 cups of dry rotini and stir everything together.","Bring to a boil over high heat, then reduce to medium. Cook uncovered for 12–14 minutes, stirring every 2–3 minutes, until the pasta is tender and the sauce has thickened.","Return the sausage to the pot. Stir in ½ cup grated Parmesan until melted into the sauce. Top with chopped parsley and serve."],"cuisine":"American","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null},"after":{"id":"7536d75f-5abd-404a-9755-c8f28a828992","title":"One-Pot Creamy Sausage Pasta","description":"Smoked sausage, rotini pasta, and diced tomatoes simmered together in a creamy, spiced sauce — everything cooks in one pot and the pasta soaks up the flavor as it goes. Stirring every few minutes during the uncovered simmer prevents sticking and helps the sauce thicken evenly.","meal_time":["dinner"],"prep_time_mins":25,"effort_score":2,"tags":["sausage","pasta","one-pot","comfort-food","quick","kid-friendly"],"image_url":"","ingredients_list":["14 oz smoked sausage (kielbasa), sliced into ½-inch rounds","2 cups dry rotini or penne pasta","2 cups chicken broth","1 cup heavy cream","14 oz diced tomatoes (1 can), with liquid","½ yellow onion, finely diced","4 cloves garlic, minced","1 tbsp olive oil","1 tsp Italian seasoning","½ tsp smoked paprika","½ tsp salt","¼ tsp black pepper","½ cup Parmesan cheese, grated","2 tbsp fresh parsley, chopped"],"shopping_list":["🥩 Proteins: smoked sausage (kielbasa)","🧀 Dairy: heavy cream, Parmesan cheese block","🥬 Produce: yellow onion, garlic, fresh parsley","🥫 Canned: chicken broth, diced tomatoes","🫙 Pantry: rotini or penne pasta, olive oil, Italian seasoning, smoked paprika, salt, black pepper"],"recipe_steps":["Slice sausage into ½-inch rounds. Dice onion, mince garlic, grate Parmesan, and chop parsley.","Heat 1 tbsp olive oil in a large pot over medium-high heat. Add sausage rounds and cook for 3 minutes until browned on one side, then flip and cook 2 more minutes. Transfer to a plate.","Add the diced onion to the pot and cook for 3 minutes, stirring occasionally. Add the minced garlic and cook 1 minute, stirring constantly.","Add 1 tsp Italian seasoning, ½ tsp smoked paprika, ½ tsp salt, and ¼ tsp black pepper. Stir for 30 seconds.","Pour in 2 cups chicken broth, 1 cup heavy cream, and one 14-oz can of diced tomatoes with all its liquid. Add 2 cups of dry rotini and stir everything together.","Bring to a boil over high heat, then reduce to medium. Cook uncovered for 12–14 minutes, stirring every 2–3 minutes, until the pasta is tender and the sauce has thickened.","Return the sausage to the pot. Stir in ½ cup grated Parmesan until melted into the sauce. Top with chopped parsley and serve."],"cuisine":"American","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null}},{"before":{"id":"c0e1fab4-8370-440b-a1a6-fc4911ab7a8e","title":"Pan-Seared Pork Chops with Pan Gravy","description":"Thick bone-in pork chops seared to a golden crust and served with a rich pan gravy built from the drippings left in the skillet. Scraping up every browned bit when the broth hits the pan is where all the gravy''s flavor comes from.","meal_time":["dinner"],"prep_time_mins":25,"effort_score":2,"tags":["pork","one-pan","comfort-food","impressive","gravy","quick"],"image_url":"https://files.manuscdn.com/user_upload_by_module/session_file/310519663417307705/XUkBeFJKDojOZilf.jpg","ingredients_list":["4 bone-in pork chops, ¾-inch thick","3 cloves garlic, minced","2 tbsp unsalted butter, divided","1 tbsp olive oil","1 cup chicken broth","¼ cup heavy cream","1 tbsp all-purpose flour, plus more for dusting","½ tsp garlic powder","½ tsp onion powder","½ tsp smoked paprika","½ tsp dried thyme","½ tsp salt","¼ tsp black pepper","2 tbsp fresh parsley, chopped","Mashed potatoes or egg noodles, for serving"],"shopping_list":["🥩 Proteins: bone-in pork chops","🧀 Dairy: unsalted butter, heavy cream","🥬 Produce: garlic, fresh parsley","🥫 Canned: chicken broth","🫙 Pantry: olive oil, all-purpose flour, garlic powder, onion powder, smoked paprika, dried thyme, salt, black pepper"],"recipe_steps":["Pat 4 pork chops dry. Season both sides with ½ tsp salt, ¼ tsp black pepper, ½ tsp garlic powder, and ½ tsp smoked paprika. Dust both sides lightly with flour and shake off excess. Mince garlic and chop parsley.","Heat 1 tbsp olive oil and 1 tbsp butter together in a large skillet over medium-high heat. Place all 4 chops in the hot skillet.","Cook for 4 minutes without moving until deeply golden brown on the bottom. Flip each chop and cook for 3–4 more minutes until the second side is golden and cooked through.","Transfer the chops to a plate and tent loosely with foil to keep warm.","Reduce heat to medium. Add 1 tbsp butter and the minced garlic to the skillet. Cook for 1 minute, stirring constantly.","Add ½ tsp dried thyme, ½ tsp onion powder, and 1 tbsp flour. Stir the flour into the butter for 1 minute. Pour in 1 cup chicken broth, scraping up all the browned bits from the bottom. Add ¼ cup heavy cream and whisk for 2–3 minutes until the gravy thickens. Season with salt if needed.","Return the pork chops to the skillet, spoon gravy over each chop, and cook 1 more minute to warm through. Sprinkle with chopped parsley and serve with mashed potatoes or egg noodles."],"cuisine":"American","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null},"after":{"id":"c0e1fab4-8370-440b-a1a6-fc4911ab7a8e","title":"Pan-Seared Pork Chops with Pan Gravy","description":"Thick bone-in pork chops seared to a golden crust and served with a rich pan gravy built from the drippings left in the skillet. Scraping up every browned bit when the broth hits the pan is where all the gravy''s flavor comes from.","meal_time":["dinner"],"prep_time_mins":25,"effort_score":2,"tags":["pork","one-pan","comfort-food","impressive","gravy","quick"],"image_url":"","ingredients_list":["4 bone-in pork chops, ¾-inch thick","3 cloves garlic, minced","2 tbsp unsalted butter, divided","1 tbsp olive oil","1 cup chicken broth","¼ cup heavy cream","1 tbsp all-purpose flour, plus more for dusting","½ tsp garlic powder","½ tsp onion powder","½ tsp smoked paprika","½ tsp dried thyme","½ tsp salt","¼ tsp black pepper","2 tbsp fresh parsley, chopped","Mashed potatoes or egg noodles, for serving"],"shopping_list":["🥩 Proteins: bone-in pork chops","🧀 Dairy: unsalted butter, heavy cream","🥬 Produce: garlic, fresh parsley","🥫 Canned: chicken broth","🫙 Pantry: olive oil, all-purpose flour, garlic powder, onion powder, smoked paprika, dried thyme, salt, black pepper"],"recipe_steps":["Pat 4 pork chops dry. Season both sides with ½ tsp salt, ¼ tsp black pepper, ½ tsp garlic powder, and ½ tsp smoked paprika. Dust both sides lightly with flour and shake off excess. Mince garlic and chop parsley.","Heat 1 tbsp olive oil and 1 tbsp butter together in a large skillet over medium-high heat. Place all 4 chops in the hot skillet.","Cook for 4 minutes without moving until deeply golden brown on the bottom. Flip each chop and cook for 3–4 more minutes until the second side is golden and cooked through.","Transfer the chops to a plate and tent loosely with foil to keep warm.","Reduce heat to medium. Add 1 tbsp butter and the minced garlic to the skillet. Cook for 1 minute, stirring constantly.","Add ½ tsp dried thyme, ½ tsp onion powder, and 1 tbsp flour. Stir the flour into the butter for 1 minute. Pour in 1 cup chicken broth, scraping up all the browned bits from the bottom. Add ¼ cup heavy cream and whisk for 2–3 minutes until the gravy thickens. Season with salt if needed.","Return the pork chops to the skillet, spoon gravy over each chop, and cook 1 more minute to warm through. Sprinkle with chopped parsley and serve with mashed potatoes or egg noodles."],"cuisine":"American","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null}},{"before":{"id":"f6c1b1e2-47a5-488b-a9d1-4adf2f4a3f39","title":"Quick Beef and Broccoli over Rice","description":"Ground beef and broccoli florets tossed in a savory soy and sesame sauce, served over steamed white rice. Whisking the cornstarch into the sauce before it hits the pan is what keeps it from clumping.","meal_time":["dinner"],"prep_time_mins":25,"effort_score":2,"tags":["beef","quick","asian","one-pan","broccoli","kid-friendly"],"image_url":"https://files.manuscdn.com/user_upload_by_module/session_file/310519663417307705/zAoWxWONrRfuZkNk.jpg","ingredients_list":["1 lb ground beef (80/20)","3 cups broccoli florets (fresh or frozen)","4 cloves garlic, minced","3 tbsp soy sauce","½ cup beef broth","1 tbsp brown sugar","1 tsp cornstarch","1 tsp sesame oil","1 tbsp vegetable oil","½ tsp garlic powder","½ tsp salt","¼ tsp black pepper","3 green onions, sliced (optional)","2 cups white rice, for serving"],"shopping_list":["🥩 Proteins: ground beef","🥬 Produce: broccoli, garlic, green onions","🥫 Canned: beef broth","🫙 Pantry: soy sauce, brown sugar, cornstarch, sesame oil, vegetable oil, garlic powder, salt, black pepper, white rice"],"recipe_steps":["Start 2 cups of white rice cooking. Cut broccoli into small florets, mince 4 cloves of garlic, and slice green onions if using.","Whisk together 3 tbsp soy sauce, ½ cup beef broth, 1 tbsp brown sugar, 1 tsp cornstarch, and 1 tsp sesame oil until the cornstarch fully dissolves. Set aside.","Heat 1 tbsp vegetable oil in a large skillet over high heat. Add the broccoli florets and cook for 4 minutes, stirring occasionally, until bright green and slightly tender. Transfer to a plate.","Add 1 lb ground beef to the skillet. Break into crumbles and add ½ tsp garlic powder, ½ tsp salt, and ¼ tsp black pepper. Cook for 5 minutes until no pink remains. Drain excess fat.","Add the minced garlic and cook for 1 minute, stirring constantly.","Return the broccoli to the skillet. Pour the sauce over everything and toss to combine.","Cook for 2–3 minutes, stirring constantly, until the sauce thickens and coats everything evenly. Serve over rice and scatter sliced green onions over the top if desired."],"cuisine":"Asian","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null},"after":{"id":"f6c1b1e2-47a5-488b-a9d1-4adf2f4a3f39","title":"Quick Beef and Broccoli over Rice","description":"Ground beef and broccoli florets tossed in a savory soy and sesame sauce, served over steamed white rice. Whisking the cornstarch into the sauce before it hits the pan is what keeps it from clumping.","meal_time":["dinner"],"prep_time_mins":25,"effort_score":2,"tags":["beef","quick","asian","one-pan","broccoli","kid-friendly"],"image_url":"","ingredients_list":["1 lb ground beef (80/20)","3 cups broccoli florets (fresh or frozen)","4 cloves garlic, minced","3 tbsp soy sauce","½ cup beef broth","1 tbsp brown sugar","1 tsp cornstarch","1 tsp sesame oil","1 tbsp vegetable oil","½ tsp garlic powder","½ tsp salt","¼ tsp black pepper","3 green onions, sliced (optional)","2 cups white rice, for serving"],"shopping_list":["🥩 Proteins: ground beef","🥬 Produce: broccoli, garlic, green onions","🥫 Canned: beef broth","🫙 Pantry: soy sauce, brown sugar, cornstarch, sesame oil, vegetable oil, garlic powder, salt, black pepper, white rice"],"recipe_steps":["Start 2 cups of white rice cooking. Cut broccoli into small florets, mince 4 cloves of garlic, and slice green onions if using.","Whisk together 3 tbsp soy sauce, ½ cup beef broth, 1 tbsp brown sugar, 1 tsp cornstarch, and 1 tsp sesame oil until the cornstarch fully dissolves. Set aside.","Heat 1 tbsp vegetable oil in a large skillet over high heat. Add the broccoli florets and cook for 4 minutes, stirring occasionally, until bright green and slightly tender. Transfer to a plate.","Add 1 lb ground beef to the skillet. Break into crumbles and add ½ tsp garlic powder, ½ tsp salt, and ¼ tsp black pepper. Cook for 5 minutes until no pink remains. Drain excess fat.","Add the minced garlic and cook for 1 minute, stirring constantly.","Return the broccoli to the skillet. Pour the sauce over everything and toss to combine.","Cook for 2–3 minutes, stirring constantly, until the sauce thickens and coats everything evenly. Serve over rice and scatter sliced green onions over the top if desired."],"cuisine":"Asian","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null}},{"before":{"id":"96622c69-2738-404e-afef-ae34f9e507ab","title":"Sausage and Potato Skillet","description":"Crispy Yukon Gold potatoes, browned smoked sausage, and sautéed peppers and onions all cooked together in one heavy skillet. Resisting the urge to stir the potatoes for the first 8 minutes is what gets them genuinely crispy.","meal_time":["dinner","breakfast"],"prep_time_mins":28,"effort_score":2,"tags":["sausage","one-pan","comfort-food","kid-friendly","potato","quick"],"image_url":"https://files.manuscdn.com/user_upload_by_module/session_file/310519663417307705/EpQxMfmBUgTLmfAo.jpg","ingredients_list":["14 oz smoked sausage (kielbasa), sliced into ½-inch rounds","1½ lbs Yukon Gold potatoes, cut into ½-inch cubes","1 green bell pepper, diced","1 yellow onion, diced","3 cloves garlic, minced","2 tbsp olive oil","1 tsp smoked paprika","½ tsp garlic powder","½ tsp Italian seasoning","½ tsp salt","¼ tsp black pepper","½ cup cheddar cheese, grated (optional)","2 tbsp fresh parsley, chopped"],"shopping_list":["🥩 Proteins: smoked sausage (kielbasa)","🧀 Dairy: cheddar cheese block (optional)","🥬 Produce: Yukon Gold potatoes, green bell pepper, yellow onion, garlic, fresh parsley","🫙 Pantry: olive oil, smoked paprika, garlic powder, Italian seasoning, salt, black pepper"],"recipe_steps":["Slice sausage into ½-inch rounds. Cube potatoes into ½-inch pieces (no need to peel). Dice bell pepper and onion, mince garlic, chop parsley, and grate cheese if using.","Heat 2 tbsp olive oil in a large heavy skillet over medium-high heat. Add the potato cubes in a single layer and cook for 8 minutes without stirring until golden brown on the bottom.","Flip the potatoes and cook for 5 more minutes until golden on the second side.","Add the sausage rounds and cook for 3 minutes until they begin to brown.","Add the diced bell pepper and onion. Stir and cook for 4 minutes until softened.","Add the minced garlic and cook for 1 minute, stirring constantly. Add 1 tsp smoked paprika, ½ tsp garlic powder, ½ tsp Italian seasoning, ½ tsp salt, and ¼ tsp black pepper. Toss to coat and cook 2 more minutes.","Sprinkle grated cheddar over the top if using, cover for 1 minute to melt, then top with chopped parsley and serve."],"cuisine":"American","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null},"after":{"id":"96622c69-2738-404e-afef-ae34f9e507ab","title":"Sausage and Potato Skillet","description":"Crispy Yukon Gold potatoes, browned smoked sausage, and sautéed peppers and onions all cooked together in one heavy skillet. Resisting the urge to stir the potatoes for the first 8 minutes is what gets them genuinely crispy.","meal_time":["dinner","breakfast"],"prep_time_mins":28,"effort_score":2,"tags":["sausage","one-pan","comfort-food","kid-friendly","potato","quick"],"image_url":"","ingredients_list":["14 oz smoked sausage (kielbasa), sliced into ½-inch rounds","1½ lbs Yukon Gold potatoes, cut into ½-inch cubes","1 green bell pepper, diced","1 yellow onion, diced","3 cloves garlic, minced","2 tbsp olive oil","1 tsp smoked paprika","½ tsp garlic powder","½ tsp Italian seasoning","½ tsp salt","¼ tsp black pepper","½ cup cheddar cheese, grated (optional)","2 tbsp fresh parsley, chopped"],"shopping_list":["🥩 Proteins: smoked sausage (kielbasa)","🧀 Dairy: cheddar cheese block (optional)","🥬 Produce: Yukon Gold potatoes, green bell pepper, yellow onion, garlic, fresh parsley","🫙 Pantry: olive oil, smoked paprika, garlic powder, Italian seasoning, salt, black pepper"],"recipe_steps":["Slice sausage into ½-inch rounds. Cube potatoes into ½-inch pieces (no need to peel). Dice bell pepper and onion, mince garlic, chop parsley, and grate cheese if using.","Heat 2 tbsp olive oil in a large heavy skillet over medium-high heat. Add the potato cubes in a single layer and cook for 8 minutes without stirring until golden brown on the bottom.","Flip the potatoes and cook for 5 more minutes until golden on the second side.","Add the sausage rounds and cook for 3 minutes until they begin to brown.","Add the diced bell pepper and onion. Stir and cook for 4 minutes until softened.","Add the minced garlic and cook for 1 minute, stirring constantly. Add 1 tsp smoked paprika, ½ tsp garlic powder, ½ tsp Italian seasoning, ½ tsp salt, and ¼ tsp black pepper. Toss to coat and cook 2 more minutes.","Sprinkle grated cheddar over the top if using, cover for 1 minute to melt, then top with chopped parsley and serve."],"cuisine":"American","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null}},{"before":{"id":"26c4a3e4-625c-431c-b68e-506ff4c18870","title":"Sheet Pan Sausage and Peppers","description":"Smoked sausage, bell peppers, and onions roasted together on one pan until the edges char and the flavors concentrate. A 425°F oven is hot enough to get real browning — don''t go lower or it''ll just steam.","meal_time":["dinner","lunch"],"prep_time_mins":25,"effort_score":1,"tags":["sausage","one-pan","quick","kid-friendly","comfort-food","baked"],"image_url":"https://files.manuscdn.com/user_upload_by_module/session_file/310519663417307705/wRhjODjmXlNMzoTO.jpg","ingredients_list":["14 oz smoked sausage (kielbasa), sliced into ½-inch rounds","1 green bell pepper, sliced into strips","1 red bell pepper, sliced into strips","1 yellow onion, sliced into ½-inch strips","2 tbsp olive oil","1 tsp garlic powder","1 tsp Italian seasoning","½ tsp smoked paprika","½ tsp salt","¼ tsp black pepper","2 cups white rice, for serving"],"shopping_list":["🥩 Proteins: smoked sausage (kielbasa)","🥬 Produce: green bell pepper, red bell pepper, yellow onion","🫙 Pantry: olive oil, garlic powder, Italian seasoning, smoked paprika, salt, black pepper, white rice"],"recipe_steps":["Preheat oven to 425°F and line a large baking sheet with aluminum foil. Start 2 cups of white rice cooking according to package directions.","Slice 14 oz of smoked sausage into ½-inch rounds. Slice 1 green bell pepper, 1 red bell pepper, and 1 yellow onion into strips.","Spread the sausage, peppers, and onion on the baking sheet. Drizzle with 2 tbsp olive oil.","Sprinkle 1 tsp garlic powder, 1 tsp Italian seasoning, ½ tsp smoked paprika, ½ tsp salt, and ¼ tsp black pepper over everything. Toss to coat evenly and spread into a single layer.","Roast for 20 minutes until the sausage is browned and the vegetables are tender with slightly charred edges.","Serve over the cooked white rice."],"cuisine":"American","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null},"after":{"id":"26c4a3e4-625c-431c-b68e-506ff4c18870","title":"Sheet Pan Sausage and Peppers","description":"Smoked sausage, bell peppers, and onions roasted together on one pan until the edges char and the flavors concentrate. A 425°F oven is hot enough to get real browning — don''t go lower or it''ll just steam.","meal_time":["dinner","lunch"],"prep_time_mins":25,"effort_score":1,"tags":["sausage","one-pan","quick","kid-friendly","comfort-food","baked"],"image_url":"","ingredients_list":["14 oz smoked sausage (kielbasa), sliced into ½-inch rounds","1 green bell pepper, sliced into strips","1 red bell pepper, sliced into strips","1 yellow onion, sliced into ½-inch strips","2 tbsp olive oil","1 tsp garlic powder","1 tsp Italian seasoning","½ tsp smoked paprika","½ tsp salt","¼ tsp black pepper","2 cups white rice, for serving"],"shopping_list":["🥩 Proteins: smoked sausage (kielbasa)","🥬 Produce: green bell pepper, red bell pepper, yellow onion","🫙 Pantry: olive oil, garlic powder, Italian seasoning, smoked paprika, salt, black pepper, white rice"],"recipe_steps":["Preheat oven to 425°F and line a large baking sheet with aluminum foil. Start 2 cups of white rice cooking according to package directions.","Slice 14 oz of smoked sausage into ½-inch rounds. Slice 1 green bell pepper, 1 red bell pepper, and 1 yellow onion into strips.","Spread the sausage, peppers, and onion on the baking sheet. Drizzle with 2 tbsp olive oil.","Sprinkle 1 tsp garlic powder, 1 tsp Italian seasoning, ½ tsp smoked paprika, ½ tsp salt, and ¼ tsp black pepper over everything. Toss to coat evenly and spread into a single layer.","Roast for 20 minutes until the sausage is browned and the vegetables are tender with slightly charred edges.","Serve over the cooked white rice."],"cuisine":"American","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null}},{"before":{"id":"5d47553f-e017-4ef9-9f01-8982fce494f4","title":"Simple Bean and Cheese Burritos","description":"Seasoned refried beans and melted cheddar wrapped in a warm flour tortilla — fast, filling, and budget-friendly. Crisping the seam-side down in a dry skillet is what keeps the burrito from unraveling and adds a satisfying crunch.","meal_time":["dinner","lunch"],"prep_time_mins":15,"effort_score":1,"tags":["vegetarian","quick","kid-friendly","mexican","budget","beans"],"image_url":"https://files.manuscdn.com/user_upload_by_module/session_file/310519663417307705/ewVbFOaAuzKgyuYM.jpg","ingredients_list":["8 large flour tortillas (10-inch)","16 oz refried beans (1 can)","1½ cups cheddar cheese, grated","½ tsp cumin","½ tsp garlic powder","¼ tsp chili powder","Sour cream, for serving","Salsa, for serving","Hot sauce, optional"],"shopping_list":["🧀 Dairy: cheddar cheese block, sour cream","🥫 Canned: refried beans","🍞 Bread: large flour tortillas","🛒 Other: salsa, hot sauce","🫙 Pantry: cumin, garlic powder, chili powder"],"recipe_steps":["Grate 1½ cups of cheddar cheese.","Pour one 16-oz can of refried beans into a medium saucepan over medium heat. Add ½ tsp cumin, ½ tsp garlic powder, and ¼ tsp chili powder. Stir and cook for 3–4 minutes until heated through and smooth.","Warm one flour tortilla in a dry skillet over medium heat for 20 seconds per side.","Lay the warm tortilla flat. Spoon 3 tbsp of seasoned beans down the center, sprinkle with 3 tbsp of cheddar, and add hot sauce if desired.","Fold the left and right sides in over the filling, then roll up tightly from the bottom. Place seam-side down in the skillet.","Cook for 1 minute until lightly golden on the bottom, then flip and cook 1 more minute.","Repeat with remaining tortillas. Serve with sour cream and salsa on the side."],"cuisine":"Mexican","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null},"after":{"id":"5d47553f-e017-4ef9-9f01-8982fce494f4","title":"Simple Bean and Cheese Burritos","description":"Seasoned refried beans and melted cheddar wrapped in a warm flour tortilla — fast, filling, and budget-friendly. Crisping the seam-side down in a dry skillet is what keeps the burrito from unraveling and adds a satisfying crunch.","meal_time":["dinner","lunch"],"prep_time_mins":15,"effort_score":1,"tags":["vegetarian","quick","kid-friendly","mexican","budget","beans"],"image_url":"","ingredients_list":["8 large flour tortillas (10-inch)","16 oz refried beans (1 can)","1½ cups cheddar cheese, grated","½ tsp cumin","½ tsp garlic powder","¼ tsp chili powder","Sour cream, for serving","Salsa, for serving","Hot sauce, optional"],"shopping_list":["🧀 Dairy: cheddar cheese block, sour cream","🥫 Canned: refried beans","🍞 Bread: large flour tortillas","🛒 Other: salsa, hot sauce","🫙 Pantry: cumin, garlic powder, chili powder"],"recipe_steps":["Grate 1½ cups of cheddar cheese.","Pour one 16-oz can of refried beans into a medium saucepan over medium heat. Add ½ tsp cumin, ½ tsp garlic powder, and ¼ tsp chili powder. Stir and cook for 3–4 minutes until heated through and smooth.","Warm one flour tortilla in a dry skillet over medium heat for 20 seconds per side.","Lay the warm tortilla flat. Spoon 3 tbsp of seasoned beans down the center, sprinkle with 3 tbsp of cheddar, and add hot sauce if desired.","Fold the left and right sides in over the filling, then roll up tightly from the bottom. Place seam-side down in the skillet.","Cook for 1 minute until lightly golden on the bottom, then flip and cook 1 more minute.","Repeat with remaining tortillas. Serve with sour cream and salsa on the side."],"cuisine":"Mexican","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null}},{"before":{"id":"7646efc3-02b1-4406-a837-e1fed70b141a","title":"Stovetop Tuna Noodle Skillet","description":"A quick weeknight version of tuna noodle casserole made entirely on the stovetop in about 20 minutes. Using the same pot for the noodles and the sauce means less cleanup and more flavor carried through.","meal_time":["dinner","lunch"],"prep_time_mins":20,"effort_score":1,"tags":["tuna","pasta","one-pot","quick","comfort-food","kid-friendly"],"image_url":"https://files.manuscdn.com/user_upload_by_module/session_file/310519663417307705/oFjPcEfWlQeGQJml.jpg","ingredients_list":["8 oz wide egg noodles","2 cans (5 oz each) tuna in water, drained","10.5 oz cream of mushroom soup (1 can)","1 cup frozen peas","½ cup whole milk","1 cup cheddar cheese, grated","2 tbsp unsalted butter","½ tsp garlic powder","½ tsp onion powder","¼ tsp black pepper","1 tsp salt (for pasta water)"],"shopping_list":["🥩 Proteins: canned tuna in water","🧀 Dairy: whole milk, cheddar cheese block, unsalted butter","🧊 Frozen: frozen peas","🥫 Canned: cream of mushroom soup","🫙 Pantry: wide egg noodles, garlic powder, onion powder, black pepper, salt"],"recipe_steps":["Drain 2 cans of tuna completely and grate 1 cup of cheddar cheese.","Bring a large pot of water to a boil. Add 1 tsp salt and 8 oz of wide egg noodles. Cook for 7 minutes until tender, then drain and set aside.","Melt 2 tbsp butter in the same pot over medium heat. Add one 10.5-oz can of cream of mushroom soup and ½ cup of whole milk. Stir until smooth and heated through.","Add ½ tsp garlic powder, ½ tsp onion powder, and ¼ tsp black pepper. Stir to combine.","Add both cans of drained tuna and 1 cup of frozen peas. Stir into the sauce.","Add the drained egg noodles and toss until fully coated.","Sprinkle the grated cheddar over the top, stir until melted, and serve immediately from the pot."],"cuisine":"American","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null},"after":{"id":"7646efc3-02b1-4406-a837-e1fed70b141a","title":"Stovetop Tuna Noodle Skillet","description":"A quick weeknight version of tuna noodle casserole made entirely on the stovetop in about 20 minutes. Using the same pot for the noodles and the sauce means less cleanup and more flavor carried through.","meal_time":["dinner","lunch"],"prep_time_mins":20,"effort_score":1,"tags":["tuna","pasta","one-pot","quick","comfort-food","kid-friendly"],"image_url":"","ingredients_list":["8 oz wide egg noodles","2 cans (5 oz each) tuna in water, drained","10.5 oz cream of mushroom soup (1 can)","1 cup frozen peas","½ cup whole milk","1 cup cheddar cheese, grated","2 tbsp unsalted butter","½ tsp garlic powder","½ tsp onion powder","¼ tsp black pepper","1 tsp salt (for pasta water)"],"shopping_list":["🥩 Proteins: canned tuna in water","🧀 Dairy: whole milk, cheddar cheese block, unsalted butter","🧊 Frozen: frozen peas","🥫 Canned: cream of mushroom soup","🫙 Pantry: wide egg noodles, garlic powder, onion powder, black pepper, salt"],"recipe_steps":["Drain 2 cans of tuna completely and grate 1 cup of cheddar cheese.","Bring a large pot of water to a boil. Add 1 tsp salt and 8 oz of wide egg noodles. Cook for 7 minutes until tender, then drain and set aside.","Melt 2 tbsp butter in the same pot over medium heat. Add one 10.5-oz can of cream of mushroom soup and ½ cup of whole milk. Stir until smooth and heated through.","Add ½ tsp garlic powder, ½ tsp onion powder, and ¼ tsp black pepper. Stir to combine.","Add both cans of drained tuna and 1 cup of frozen peas. Stir into the sauce.","Add the drained egg noodles and toss until fully coated.","Sprinkle the grated cheddar over the top, stir until melted, and serve immediately from the pot."],"cuisine":"American","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null}},{"before":{"id":"557e9052-9f40-4a5e-96b9-dab6328f4b00","title":"Homemade Ramen","description":"Rich, deeply flavored ramen broth built by charring onion and ginger directly in a dry pot, simmered with chicken and shiitake mushrooms for an hour, then finished with soy, mirin, and sesame. The 6.5-minute soft-boiled egg is the detail that separates good ramen from great ramen.","meal_time":["dinner","lunch"],"prep_time_mins":90,"effort_score":3,"tags":["soup","asian","noodles","impressive","japanese"],"image_url":"https://yhfqlvblqlpacjdkltfi.supabase.co/storage/v1/object/public/meal-photos/hero/homemade_ramen.jpg","ingredients_list":["2 lbs bone-in, skin-on chicken thighs","6 cups low-sodium chicken broth","2 cups low-sodium beef broth","1 large yellow onion, halved (skin on)","6 garlic cloves, smashed","2-inch piece fresh ginger, sliced into rounds","1/2 cup dried shiitake mushrooms","3 tbsp soy sauce","2 tbsp mirin","1 tsp sesame oil","1 tsp sugar","Salt, to taste","12 oz fresh or dried ramen noodles","4 large eggs","2 small heads baby bok choy, halved lengthwise","4 green onions, thinly sliced","1/2 cup corn kernels (canned or frozen)","4 tsp sesame seeds","Chili oil or sriracha, for serving","Nori sheets, for serving (optional)"],"shopping_list":["🥩 Proteins: bone-in, skin-on chicken thighs, low-sodium chicken broth, low-sodium beef broth, large eggs","🥬 Produce: yellow onion, garlic cloves, fresh ginger, baby bok choy, green onions","🧊 Frozen: corn kernels (or canned)","🍞 Bread: fresh or dried ramen noodles","🛒 Other: dried shiitake mushrooms, soy sauce, mirin, sesame oil, sugar, sesame seeds, chili oil or sriracha, nori sheets (optional)"],"recipe_steps":["Halve 1 yellow onion skin-on. Smash 6 garlic cloves. Slice a 2-inch piece of ginger into rounds. Halve 2 baby bok choy lengthwise. Slice 4 green onions.","Heat a large pot over high heat until very hot. Place the onion halves cut-side down in the dry pot. Char for 3-4 minutes without moving until deeply browned. Add the smashed garlic and ginger slices and char for 2 more minutes.","Add 2 lbs chicken thighs, 6 cups chicken broth, 2 cups beef broth, and 1/2 cup dried shiitake mushrooms. Bring to a boil then reduce to low. Simmer uncovered for 1 hour.","Remove the chicken thighs and transfer to a cutting board. Strain the broth through a fine-mesh strainer into a clean pot, discarding all solids.","Add 3 tbsp soy sauce, 2 tbsp mirin, 1 tsp sesame oil, and 1 tsp sugar to the strained broth. Taste and add salt as needed. Keep warm over low heat. Pull the chicken meat from the bones, shred into bite-sized pieces, and discard skin and bones.","Bring a small saucepan of water to a boil. Lower 4 eggs gently into the water. Cook for exactly 6 minutes 30 seconds. Transfer immediately to an ice bath for 5 minutes. Peel carefully and halve lengthwise.","Blanch the halved bok choy in boiling water for 1 minute. Remove with tongs and set aside. Cook 12 oz ramen noodles in salted boiling water for 2-3 minutes until just tender. Drain.","Ladle 1 1/2 cups of hot broth into each of 4 deep bowls. Divide the noodles among the bowls.","Arrange the shredded chicken, 2 bok choy halves, 2 egg halves yolk-side up, 2 tbsp corn, sliced green onions, and 1 tsp sesame seeds in each bowl. Add a sheet of nori if desired. Drizzle chili oil or sriracha to taste. Serve immediately."],"cuisine":"Japanese","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null},"after":{"id":"557e9052-9f40-4a5e-96b9-dab6328f4b00","title":"Homemade Ramen","description":"Rich, deeply flavored ramen broth built by charring onion and ginger directly in a dry pot, simmered with chicken and shiitake mushrooms for an hour, then finished with soy, mirin, and sesame. The 6.5-minute soft-boiled egg is the detail that separates good ramen from great ramen.","meal_time":["dinner","lunch"],"prep_time_mins":90,"effort_score":3,"tags":["soup","asian","noodles","impressive","japanese"],"image_url":"","ingredients_list":["2 lbs bone-in, skin-on chicken thighs","6 cups low-sodium chicken broth","2 cups low-sodium beef broth","1 large yellow onion, halved (skin on)","6 garlic cloves, smashed","2-inch piece fresh ginger, sliced into rounds","1/2 cup dried shiitake mushrooms","3 tbsp soy sauce","2 tbsp mirin","1 tsp sesame oil","1 tsp sugar","Salt, to taste","12 oz fresh or dried ramen noodles","4 large eggs","2 small heads baby bok choy, halved lengthwise","4 green onions, thinly sliced","1/2 cup corn kernels (canned or frozen)","4 tsp sesame seeds","Chili oil or sriracha, for serving","Nori sheets, for serving (optional)"],"shopping_list":["🥩 Proteins: bone-in, skin-on chicken thighs, low-sodium chicken broth, low-sodium beef broth, large eggs","🥬 Produce: yellow onion, garlic cloves, fresh ginger, baby bok choy, green onions","🧊 Frozen: corn kernels (or canned)","🍞 Bread: fresh or dried ramen noodles","🛒 Other: dried shiitake mushrooms, soy sauce, mirin, sesame oil, sugar, sesame seeds, chili oil or sriracha, nori sheets (optional)"],"recipe_steps":["Halve 1 yellow onion skin-on. Smash 6 garlic cloves. Slice a 2-inch piece of ginger into rounds. Halve 2 baby bok choy lengthwise. Slice 4 green onions.","Heat a large pot over high heat until very hot. Place the onion halves cut-side down in the dry pot. Char for 3-4 minutes without moving until deeply browned. Add the smashed garlic and ginger slices and char for 2 more minutes.","Add 2 lbs chicken thighs, 6 cups chicken broth, 2 cups beef broth, and 1/2 cup dried shiitake mushrooms. Bring to a boil then reduce to low. Simmer uncovered for 1 hour.","Remove the chicken thighs and transfer to a cutting board. Strain the broth through a fine-mesh strainer into a clean pot, discarding all solids.","Add 3 tbsp soy sauce, 2 tbsp mirin, 1 tsp sesame oil, and 1 tsp sugar to the strained broth. Taste and add salt as needed. Keep warm over low heat. Pull the chicken meat from the bones, shred into bite-sized pieces, and discard skin and bones.","Bring a small saucepan of water to a boil. Lower 4 eggs gently into the water. Cook for exactly 6 minutes 30 seconds. Transfer immediately to an ice bath for 5 minutes. Peel carefully and halve lengthwise.","Blanch the halved bok choy in boiling water for 1 minute. Remove with tongs and set aside. Cook 12 oz ramen noodles in salted boiling water for 2-3 minutes until just tender. Drain.","Ladle 1 1/2 cups of hot broth into each of 4 deep bowls. Divide the noodles among the bowls.","Arrange the shredded chicken, 2 bok choy halves, 2 egg halves yolk-side up, 2 tbsp corn, sliced green onions, and 1 tsp sesame seeds in each bowl. Add a sheet of nori if desired. Drizzle chili oil or sriracha to taste. Serve immediately."],"cuisine":"Japanese","created_at":"2026-03-29 12:00:00+00","servings":4,"user_id":null,"is_user_created":false,"source_url":null,"source_name":null}}]'::jsonb);
DO $photos$
DECLARE item jsonb; current_row jsonb; changed integer := 0;
BEGIN
  FOR item IN SELECT p.item FROM incoming_photo_updates p LOOP
    SELECT to_jsonb(r) INTO current_row FROM public.recipes r WHERE r.id = (item->'before'->>'id')::uuid FOR UPDATE;
    IF current_row IS NULL THEN RAISE EXCEPTION 'Photo recipe is missing'; END IF;
    IF current_row - 'created_at' = (item->'after') - 'created_at' THEN CONTINUE; END IF;
    IF current_row - 'created_at' IS DISTINCT FROM (item->'before') - 'created_at' THEN
      RAISE EXCEPTION 'Recipe changed since photo review: %', item->'before'->>'title';
    END IF;
    IF (current_row->>'is_user_created')::boolean OR current_row->>'user_id' IS NOT NULL THEN RAISE EXCEPTION 'Only shared recipes may be updated'; END IF;
    UPDATE public.recipes SET image_url = item->'after'->>'image_url', description = item->'after'->>'description' WHERE id = (item->'before'->>'id')::uuid;
    changed := changed + 1;
  END LOOP;
  RAISE NOTICE 'Updated % recipe photos', changed;
END $photos$;
COMMIT;
